var vertexShaderSrc = `#version 300 es
in vec3 vertexPosition;
in vec3 vertexNormal;
in vec2 vertexTextureCoord;
uniform mat4 modelViewTransform;
uniform mat4 modelTransform;
uniform mat4 projectionTransform;
uniform bool textureCoordinatesGenerated;
uniform vec4 planeS;
uniform vec4 planeT;
uniform mat3 textureCoordTransform;
uniform mat3 normalTransform;
uniform bool ignoreNormal;
uniform bool backFaceNormalFlip;
uniform bool lightingEnabled;
uniform bool useTextures;
out vec2 varTextureCoord;
out vec4 varVertexPosition;
out vec3 varTransformedNormal;
out vec4 positionOrigin;
void main(void) {
    positionOrigin = modelTransform * vec4(vertexPosition, 1.0);
    varVertexPosition = modelViewTransform * vec4(vertexPosition, 1.0);
    gl_Position = projectionTransform * varVertexPosition;
    if (useTextures) {
        if (textureCoordinatesGenerated) {
            varTextureCoord = vec2(vertexPosition.x * planeS.x + vertexPosition.y * planeS.y + vertexPosition.z * planeS.z + planeS.w, vertexPosition.x * planeT.x + vertexPosition.y * planeT.y + vertexPosition.z * planeT.z + planeT.w);
        } else {
            varTextureCoord = vec2(vertexTextureCoord);
        }
        varTextureCoord = vec2(textureCoordTransform * vec3(varTextureCoord, 1));
    }
    if (lightingEnabled) {
        vec3 normal;
        if (ignoreNormal) {
            normal = vec3(1., 1., 1.);
        } else {
            normal = vertexNormal;
            if (backFaceNormalFlip) {
                normal = -normal;
            }
        }
        //varTransformedNormal = normalize(normalTransform * normal);
        varTransformedNormal =  normal;
    }
}
`

var fragmentShaderSrc = `#version 300 es
precision mediump float;
uniform vec3 vertexDiffuseColor;
uniform vec3 vertexSpecularColor;
uniform float shininess;
uniform sampler2D sampler;
uniform float alpha;
uniform bool useTextures;
uniform bool lightingEnabled;
uniform vec3 ambientColor;
uniform int directionalLightCount;
uniform vec3 lightDirections[16];
uniform vec3 directionalLightColors[16];
in vec2 varTextureCoord;
in vec4 varVertexPosition;
in vec3 varTransformedNormal;
in vec4 positionOrigin;
layout( location = 0 ) out vec4 color;
layout( location = 1 ) out vec4 position;
layout( location = 2 ) out vec4 normals;
void main(void) {
    vec3 lightWeight;
    if (lightingEnabled) {
        lightWeight = ambientColor;
        if (directionalLightCount > 0) {
            vec3 diffuseLightWeight = vec3(0., 0., 0.);
            vec3 specularLightWeight = vec3(0., 0., 0.);
            vec3 eyeDirection = vec3(0., 0., 0.);
            bool computeSpecularLightWeight = false;
            if (vertexSpecularColor.r > 0. && vertexSpecularColor.g > 0. && vertexSpecularColor.b > 0.) {
                eyeDirection = normalize(-varVertexPosition.xyz);
                computeSpecularLightWeight = length(eyeDirection) <= 1.0001;
            }
            for (int i = 0; i < 16 ; i++) {
                if (i >= directionalLightCount) {
                    break;
                }
                float directionalLightWeight = max(dot(varTransformedNormal, lightDirections[i]), 0.);
                diffuseLightWeight += directionalLightColors[i] * directionalLightWeight;
                if (computeSpecularLightWeight) {
                    vec3 reflectionDirection = reflect(-lightDirections[i], varTransformedNormal);
                    specularLightWeight += directionalLightColors[i] * pow(max(dot(reflectionDirection, eyeDirection), 0.), shininess);
                }
            }
            lightWeight += vertexDiffuseColor * diffuseLightWeight;
            if (computeSpecularLightWeight) {
                lightWeight += vertexSpecularColor * specularLightWeight;
            }
        }
    } else {
        lightWeight = vertexDiffuseColor;
    }
    vec4 fragmentColor;
    if (useTextures) {
        fragmentColor = texture(sampler, vec2(varTextureCoord.s, varTextureCoord.t));
    } else {
        fragmentColor = vec4(1., 1., 1., 1.);
    }
    //gl_FragColor = vec4(fragmentColor.rgb * lightWeight * alpha, fragmentColor.a * alpha);


    color = vec4(fragmentColor.rgb * lightWeight * alpha, fragmentColor.a * alpha);
    //color =  vec4(positionOrigin.x * 0.01, positionOrigin.y* 0.01, positionOrigin.z* 0.01, 1.0);
    // color =  vec4(varTransformedNormal.xyz, 1);
    position = positionOrigin + vec4(varTransformedNormal.xyz, 0) * 0.33;
    normals = vec4(varTransformedNormal.xyz, 0);
}
`


const markerVertexShader = `#version 300 es
in vec3 coordinates;
uniform mat4 viewTransform;
uniform mat4 projectionTransform;
uniform mat4 modelTransform;
void main(void) { 
    gl_Position = projectionTransform * viewTransform * modelTransform * vec4(coordinates, 1.0);
}
`

const markerFragmentShader = `#version 300 es
precision mediump float;
uniform vec4 lineColor;
layout( location = 0 ) out vec4 color;
void main(void) {
    color = lineColor;
}
`




