        if (j.visible) {
            if ((j.transparency === undefined || j.transparency === 1) && (j.texture === undefined || !j.texture.image.transparent)) {
                this.drawGeometry(j, d, b, j.lightingEnabled, true, true);
            } else {
                if (j.transparency > 0) {
                    c.push(j);
                }
            }
        }
