HTMLCanvas3D.prototype.drawMarker = function(pos, norm, l, depth) {
    this.gl.useProgram(this.markerShaderProgram);
    if(depth) {
        this.gl.enable(this.gl.DEPTH_TEST);
    } else {
        this.gl.disable(this.gl.DEPTH_TEST);
    }

    this.gl.enableVertexAttribArray(this.markerPositionAtribute);
    this.gl.bindBuffer(this.gl.ARRAY_BUFFER, this.markerPositionBuffer);
    this.gl.vertexAttribPointer(this.markerPositionAtribute, 3, this.gl.FLOAT, false, 0, 0);

    var viewMatrix = mat4.invert(mat4.create(), this.viewPlatformTransform);
    this.gl.uniformMatrix4fv(this.markerViewTransformUniform, false, viewMatrix);
    this.gl.uniformMatrix4fv(this.markerProjeTransformUniform, false, l);


    const markerTransMat = mat4.create();
    mat4.translate(markerTransMat, markerTransMat, pos);
    //mat4.translate(markerTransMat, markerTransMat, [0,0,50]);

    const normalVector = vec3.fromValues(norm[0], norm[1], norm[2]);
    //const normalVector = vec3.fromValues(0,1, 0);
    vec3.add(normalVector, normalVector, [0., 0.0, 0.01]);
    vec3.normalize(normalVector, normalVector);

    let tangent0 = vec3.cross(vec3.create(), normalVector, vec3.fromValues(0,1,0));
    vec3.normalize(tangent0, tangent0);
    // if (vec3.dot(tangent0, tangent0) < 0.001) {
    //     tangent0 = vec3.cross(vec3.create(), normalVector, vec3.fromValues(0, 1, 0));
    // }                                             
    const tangent1 = vec3.cross(vec3.create(), normalVector, tangent0);
    vec3.normalize(tangent1, tangent1);
    const markerRotlMat = mat4.fromValues(
        tangent0[0], tangent1[0], normalVector[0], 0,
        tangent0[1], tangent1[1], normalVector[1], 0,
        tangent0[2], tangent1[2], normalVector[2], 0,
        0, 0, 0, 1,
    );

    const markerModelMat = mat4.mul(mat4.create(), markerTransMat, markerRotlMat);

    
    this.gl.uniformMatrix4fv(this.markerModelTransformUniform, false, markerModelMat);

    if(depth) {
        this.gl.uniform4f(this.markerColor, 0, 0, 1, 1);
    } else {
        this.gl.uniform4f(this.markerColor, 0.5, 0.5, 0.6, 1);
    }
    
    

    this.gl.drawArrays(this.gl.LINES, 0, this.vertices.length / 3);
    this.gl.bindBuffer(this.gl.ARRAY_BUFFER, null);
}

HTMLCanvas3D.prototype.drawMarkerDistance = function(pos0, pos1, l, depth) {
    this.gl.useProgram(this.markerShaderProgram);
    if(depth) {
        this.gl.enable(this.gl.DEPTH_TEST);
    } else {
        this.gl.disable(this.gl.DEPTH_TEST);
    }


    // Create an empty buffer object
    this.markerPositionBufferDistance = this.gl.createBuffer();

    // Bind appropriate array buffer to it
    this.gl.bindBuffer(this.gl.ARRAY_BUFFER, this.markerPositionBufferDistance);
 
    // Pass the vertex data to the buffer
    this.gl.bufferData(this.gl.ARRAY_BUFFER, new Float32Array([pos0[0], pos0[1], pos0[2], pos1[0], pos1[1], pos1[2]]), this.gl.STATIC_DRAW);

    // Unbind the buffer
    

    this.gl.vertexAttribPointer(this.markerPositionBufferDistance, 3, this.gl.FLOAT, false, 0, 0);
    this.gl.enableVertexAttribArray(this.markerPositionBufferDistance);

    var viewMatrix = mat4.invert(mat4.create(), this.viewPlatformTransform);
    this.gl.uniformMatrix4fv(this.markerViewTransformUniform, false, viewMatrix);
    this.gl.uniformMatrix4fv(this.markerProjeTransformUniform, false, l);

    const markerModelMat = mat4.create();
    
    this.gl.uniformMatrix4fv(this.markerModelTransformUniform, false, markerModelMat);

    if(depth) {
        this.gl.uniform4f(this.markerColor, 0, 0, 1, 1);
    } else {
        this.gl.uniform4f(this.markerColor, 0.5, 0.5, 0.6, 1);
    }

    this.gl.drawArrays(this.gl.LINES, 0, 6);
    this.gl.bindBuffer(this.gl.ARRAY_BUFFER, null);
}

HTMLCanvas3D.prototype.mouseMove= function(x,y) {
    var rect = this.canvas.getBoundingClientRect();
    this.mousePositionX = x - rect.left;
    this.mousePositionY = rect.bottom - y;

    const w = (rect.right - rect.left);
    const h = (rect.bottom - rect.top);
    this.mouseValid = this.mousePositionX > 0 && this.mousePositionX < w && this.mousePositionY > 0 && this.mousePositionY < h;

    this.repaint();
}

HTMLCanvas3D.prototype.mouseClick= function(x,y, button) {
    if(!this.measureToolEnabled) {
        return;
    }
    var rect = this.canvas.getBoundingClientRect();
    this.mousePositionX = x - rect.left;
    this.mousePositionY = rect.bottom - y;
    if(button == 0) {
        this.mouseClicked = true;
    }
    if(button == 2) {
        this.mouseUnlicked = true;
    }
    this.repaint();
}

HTMLCanvas3D.prototype.measureToolToggle = function() {
    this.measureToolEnabled = !this.measureToolEnabled;
    this.mtLabel.innerHTML = 'distance: -'
    this.mtLabel.style.visibility = this.measureToolEnabled ? 'visible' : 'hidden';
    this.markerSecondPoint = undefined;
    this.markerFirstPoint = undefined;
    this.repaint();
}

HTMLCanvas3D.prototype.setMTLabelElement  = function(mtLabel) {
   this.mtLabel = mtLabel;
   
   this.updateMeasureToolPosition()
}

HTMLCanvas3D.prototype.updateMeasureToolPosition = function() {
    const  canvasRect = this.canvas.getBoundingClientRect();

    const labelRect = this.mtLabel.getBoundingClientRect();
    this.mtLabel.style.top = canvasRect.top;
    this.mtLabel.style.left = canvasRect.left + (canvasRect.right - canvasRect.left - (labelRect.right - labelRect.left))/2
}


HTMLCanvas3D.prototype.updateMeasureToolValue = function(v1, v2) {

    if(v1 && v2) {
        this.mtLabel.innerHTML = 'distance: ' + Math.sqrt(Math.pow(v1[0] - v2[0], 2) +Math.pow(v1[1] - v2[1], 2) + Math.pow(v1[2] - v2[2], 2)).toFixed(2);
    } else {
        this.mtLabel.innerHTML = 'distance: -'
    }
}




