// Function to improve rendering quality for mobile devices
function enhanceNode3DRendering(renderer, camera) {
  const isMobile = window.innerWidth <= 768;

  // Set pixel ratio for sharper visuals
  renderer.setPixelRatio(window.devicePixelRatio || 1);

  // Adjust rendering resolution dynamically
  renderer.setSize(window.innerWidth, window.innerHeight);

  if (isMobile) {
    // Adjust Field of View for smaller screens
    camera.fov = 85;
    camera.updateProjectionMatrix();

    // Apply high-quality textures and anti-aliasing
    console.info("Enhancing Node3D rendering quality for mobile devices...");
    renderer.antialias = true;

    // Enable anisotropic filtering for textures
    console.info("Applying anisotropic filtering...");
    texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
  }
}

// Example usage
const renderer = new THREE.WebGLRenderer({ antialias: true });
const aspectRatio = window.innerWidth / window.innerHeight;
const camera = new THREE.PerspectiveCamera(75, aspectRatio, 0.1, 1000);

enhanceNode3DRendering(renderer, camera);

function enhanceLighting(scene) {
  console.info("Enhancing lighting for Node3D...");

  // Add a point light
  const pointLight = new THREE.PointLight(0xffffff, 2); // Intensity increased to 2
  pointLight.position.set(5, 5, 5);
  scene.add(pointLight);

  // Add a hemisphere light for soft ambient lighting
  const hemisphereLight = new THREE.HemisphereLight(0xffffff, 0x444444, 1.5); // Intensity increased to 1.5
  scene.add(hemisphereLight);

  console.info("Lighting enhanced for Node3D.");
}

